// Checks that the bot's WhatsApp templates exist and are usable, and plans what to do for each one.
// A template that is missing (deleted), disabled or paused is recreated under a new name, because Meta
// blocks reusing a deleted template's name for a while. The bot reads the name to use from the
// "WhatsApp Templates" data table.
const WABA_LIST = $('List Templates').first().json;
const listed = Array.isArray(WABA_LIST.data) ? WABA_LIST.data : [];
const listError = WABA_LIST.error ? String(WABA_LIST.error.message || JSON.stringify(WABA_LIST.error)) : '';
const saved = {};
for (const it of $input.all()) if (it.json && it.json.key) saved[it.json.key] = it.json;
const now = $now.setZone('Asia/Kolkata');
const stamp = now.toFormat('yyyy-MM-dd HH:mm');

const SHEET = 'https://docs.google.com/spreadsheets/d/1W4jmnP3XUVXk7EimIOOjTx4GcfaqHiUAXnaM1bsGiHE/edit';
const REQUIRED = [
  {
    key: 'lead',
    base: 'rc_lead_alert',
    components: [
      {
        type: 'BODY',
        text: 'New alert from the Raj Creations WhatsApp assistant.\n\nReason: {{1}}\nCustomer: {{2}}\nDetails: {{3}}\n\nPlease reply to this customer from your phone soon. This message was sent automatically by our order assistant.',
        example: { body_text: [['New WEBSITE ORDER of Rs 13,671 including GST', 'Priya, +91 98000 00000', 'Business / City: Sharma Fancy Store, Pune | Type: Retailer | Language: Hindi | Items: 322 x35 box']] },
      },
      {
        type: 'BUTTONS',
        buttons: [
          { type: 'URL', text: 'Chat with customer', url: 'https://rajcreation.info/chat/?n={{1}}', example: ['https://rajcreation.info/chat/?n=919800000000'] },
          { type: 'URL', text: 'Open leads sheet', url: SHEET },
        ],
      },
    ],
  },
  {
    // Mahek's alerts outside her 24-hour window (inside it the bot sends a normal message with buttons)
    key: 'alert',
    base: 'rc_mahek_alert',
    components: [
      {
        type: 'BODY',
        text: 'New update from the Raj Creations order assistant: {{1}}\n\nCustomer: {{2}}\nBusiness: {{3}}\nDetails: {{4}}\n\nTap a button below to chat with the customer, check their status or finalize the order.',
        example: { body_text: [['New WEBSITE ORDER RC-1007-K3F9 - Rs 11,710.13 incl. GST (41 packets)', 'Raj Gada, +91 97686 63737', 'Meeraj, Mumbai | Retailer | English', '8 items, 41 packets: TESLA-703 x1, TESLA-707 x4, CH-01 x6']] },
      },
      {
        type: 'BUTTONS',
        buttons: [
          { type: 'QUICK_REPLY', text: 'Finalize order' },
          { type: 'QUICK_REPLY', text: 'Status' },
          { type: 'QUICK_REPLY', text: 'Pause bot' },
          { type: 'URL', text: 'Chat with customer', url: 'https://rajcreation.info/chat/?n={{1}}', example: ['https://rajcreation.info/chat/?n=919800000000'] },
          { type: 'URL', text: 'Open leads sheet', url: SHEET },
        ],
      },
    ],
  },
  {
    // order confirmation for a customer whose 24-hour window is closed: the button sends them the PDF
    key: 'confirm',
    base: 'rc_order_confirmed',
    components: [
      {
        type: 'BODY',
        text: 'Hello {{1}}, your Raj Creations order {{2}} is confirmed.\n\nTotal: {{3}}\n\nTap the button below to get your order confirmation PDF. If you have any questions, just reply to this message.',
        example: { body_text: [['Priya', 'RC-1007-K3F9', 'Rs 12,060.13 (incl. GST and shipping)']] },
      },
      { type: 'BUTTONS', buttons: [{ type: 'QUICK_REPLY', text: 'Get confirmation PDF' }] },
    ],
  },
  {
    // order changes from Mahek's order page (rajcreation.info/orders/) for a customer whose 24-hour window is closed
    key: 'update',
    base: 'rc_order_update',
    components: [
      {
        type: 'BODY',
        text: 'Hello {{1}}, there are some changes to your Raj Creation order {{2}}.\n\nChanges: {{3}}\n\nNew total: {{4}}\n\nIf you have any questions or would like something else instead, just reply to this message.',
        example: { body_text: [['Priya', 'RC-1007-K3F9', 'RC-500 - only 3 packets available (you ordered 8); RC-600 - out of stock, replaced with RC-700 x 9 packets', 'Rs 3,858.75 incl. GST + shipping Rs 350']] },
      },
    ],
  },
  {
    key: 'problem',
    base: 'rc_bot_problem',
    components: [
      {
        type: 'BODY',
        text: 'The Raj Creations WhatsApp assistant had a problem.\n\nStep: {{1}}\nError: {{2}}\nTime: {{3}}\n\nA customer may not have received a reply. Please check recent chats and the n8n executions list.',
        example: { body_text: [['Send Welcome Message', 'Request timed out', '03 Oct 2026, 12:00 PM']] },
      },
      {
        type: 'BUTTONS',
        buttons: [{ type: 'URL', text: 'Open n8n', url: 'https://gadaironman.app.n8n.cloud/workflow/OZLCCBDrLeivkkMf/executions' }],
      },
    ],
  },
];

const RANK = { APPROVED: 3, PENDING: 2, IN_APPEAL: 2, REJECTED: 1 };
const out = [];
for (const req of REQUIRED) {
  const prev = saved[req.key] || {};
  const mine = listed.filter((t) => (t.name === req.base || String(t.name).startsWith(req.base + '_')) && t.language === 'en_US');
  // best usable copy: approved first, the one already in use preferred, then the newest name
  mine.sort((a, b) => (RANK[b.status] || 0) - (RANK[a.status] || 0) || (b.name === prev.name) - (a.name === prev.name) || String(b.name).localeCompare(String(a.name)));
  const best = mine[0];
  const seen = mine.map((t) => t.name + '=' + t.status).join(', ') || 'none';
  let action = 'ok';
  let name = best ? best.name : (prev.name || req.base);
  let status = best ? best.status : 'MISSING';
  let note = '';
  if (listError) {
    action = 'skip';
    status = prev.status || 'UNKNOWN';
    note = 'Could not read templates from Meta: ' + listError.slice(0, 300);
  } else if (!best || ['DISABLED', 'PAUSED', 'DELETED', 'PENDING_DELETION', 'ARCHIVED'].includes(best.status)) {
    // at most one new copy a day: if copies keep vanishing, something is deleting them and resubmitting won't help
    const lastMade = String(prev.history || '').split('\n').find((l) => l.includes('| creating '));
    const madeAt = lastMade ? DateTime.fromFormat(lastMade.slice(0, 16), 'yyyy-MM-dd HH:mm', { zone: 'Asia/Kolkata' }) : null;
    const hoursAgo = madeAt && madeAt.isValid ? now.diff(madeAt, 'hours').hours : Infinity;
    let runNow = false; // a manual "Run Now" always makes a new copy
    try { runNow = $('Run Now').isExecuted; } catch (e) { runNow = false; }
    if (hoursAgo < 24 && !runNow) {
      action = 'wait';
      note = 'The copy made ' + Math.round(hoursAgo) + ' h ago was deleted again – something with access to the WhatsApp account (AiSensy / automessage?) is deleting templates. Next new copy after 24 h.';
    } else {
      action = 'create';
      note = best ? best.name + ' is ' + best.status + ' – created a new copy' : 'No ' + req.base + ' template found at Meta (deleted?) – created a new copy';
    }
  } else if (best.status === 'REJECTED') {
    note = best.name + ' was REJECTED by Meta' + (best.rejected_reason && best.rejected_reason !== 'NONE' ? ' (' + best.rejected_reason + ')' : '') + ' – not recreated automatically, please check the wording';
  } else if (best.status !== 'APPROVED') {
    note = best.name + ' is ' + best.status + ' (waiting for Meta)';
  } else {
    note = best.name + ' approved';
  }
  const newName = req.base + '_' + now.toFormat('ddLLyyHHmm');
  const changed = action === 'create' || status !== prev.status || name !== prev.name;
  const history = String((changed ? stamp + ' | ' + status + ' ' + name + ' | seen: ' + seen + (action === 'create' ? ' | creating ' + newName : '') + '\n' : '') + (prev.history || '')).slice(0, 3000);
  out.push({
    json: {
      key: req.key,
      name,
      status,
      checked_at: stamp,
      note,
      history,
      need_create: action === 'create',
      new_name: newName,
      create_body: { name: newName, language: 'en_US', category: 'UTILITY', components: req.components },
    },
  });
}
return out;

// Result of creating a new template copy: use it if Meta accepted it, otherwise keep the old name and say why.
const plan = $('Plan').item.json;
const r = $json;
const err = r.error ? String(r.error.message || r.error.description || JSON.stringify(r.error)).slice(0, 300) : '';
if (r.id && !err) {
  return { json: Object.assign({}, plan, {
    name: plan.new_name,
    status: r.status || 'PENDING',
    note: plan.note + ' → ' + plan.new_name + ' submitted (' + (r.status || 'PENDING') + ', ' + (r.category || 'UTILITY') + ')',
  }) };
}
return { json: Object.assign({}, plan, {
  note: plan.note + ' → creating ' + plan.new_name + ' FAILED: ' + (err || JSON.stringify(r).slice(0, 300)),
  history: (plan.checked_at + ' | create failed: ' + (err || 'unknown') + '\n' + plan.history).slice(0, 3000),
}) };
